import signal

from validator import is_valid_email


class _Timeout(Exception):
    pass


def _run_with_alarm(fn, seconds):
    def _handler(signum, frame):
        raise _Timeout()

    old = signal.signal(signal.SIGALRM, _handler)
    signal.alarm(seconds)
    try:
        return fn()
    finally:
        signal.alarm(0)
        signal.signal(signal.SIGALRM, old)


def test_valid_emails_still_accepted():
    assert is_valid_email('user@example.com') is True
    assert is_valid_email('user.name123@sub.example.com') is True


def test_invalid_emails_still_rejected():
    assert is_valid_email('not-an-email') is False
    assert is_valid_email('@example.com') is False


def test_pathological_input_does_not_hang():
    payload = 'a' * 30 + '!'
    try:
        result = _run_with_alarm(lambda: is_valid_email(payload), seconds=4)
    except _Timeout:
        raise AssertionError('is_valid_email took more than 4s on a pathological input - still vulnerable to catastrophic backtracking')
    assert result is False

